// ResetPasswordScreen.jsx
import { useState } from "react";
import { confirmPasswordReset, verifyPasswordResetCode } from "firebase/auth";
import { auth } from "../firebase";

const BEAST_ICON_B64 = "";

export default function ResetPasswordScreen({ oobCode }) {
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [status, setStatus] = useState("idle");
  const [errorMsg, setErrorMsg] = useState("");

  async function handleSubmit() {
    if (!password || password.length < 6) { setErrorMsg("La contraseña debe tener al menos 6 caracteres."); return; }
    if (password !== confirm) { setErrorMsg("Las contraseñas no coinciden."); return; }
    setErrorMsg(""); setStatus("loading");
    try {
      await verifyPasswordResetCode(auth, oobCode);
      await confirmPasswordReset(auth, oobCode, password);
      setStatus("success");
    } catch (e) {
      setStatus("error");
      if (e.code === "auth/expired-action-code") setErrorMsg("El enlace expiró. Solicita uno nuevo.");
      else if (e.code === "auth/invalid-action-code") setErrorMsg("El enlace no es válido o ya fue usado.");
      else if (e.code === "auth/weak-password") setErrorMsg("Contraseña muy débil. Usa al menos 6 caracteres.");
      else setErrorMsg("Ocurrió un error. Intenta de nuevo.");
    }
  }

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@700;900&family=Barlow:wght@400;500;700&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { background: #080808; }
        .rp-page {
          min-height: 100vh;
          background: #080808;
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          padding: 24px;
          position: relative;
          overflow: hidden;
        }
        .rp-bg-glow {
          position: absolute;
          width: 500px; height: 500px;
          border-radius: 50%;
          background: radial-gradient(circle, rgba(223,255,0,0.06) 0%, transparent 70%);
          top: -100px; left: 50%; transform: translateX(-50%);
          pointer-events: none;
        }
        .rp-logo {
          text-align: center;
          margin-bottom: 28px;
          position: relative;
          z-index: 1;
        }
        .rp-icon {
          width: 52px; height: 52px;
          border-radius: 14px;
          overflow: hidden;
          margin: 0 auto 10px;
          box-shadow: 0 0 28px rgba(223,255,0,0.35);
        }
        .rp-icon img { width: 100%; height: 100%; object-fit: cover; }
        .rp-appname {
          font-family: 'Inter', sans-serif;
          font-size: 26px; font-weight: 900;
          letter-spacing: 7px; color: white;
          text-transform: uppercase; line-height: 1;
        }
        .rp-slogan-row {
          display: flex; align-items: center; gap: 8px; margin-top: 10px; justify-content: center;
        }
        .rp-line { width: 20px; height: 2px; background: #DFFF00; border-radius: 1px; }
        .rp-slogan {
          font-family: 'Inter', sans-serif;
          font-size: 11px; font-weight: 700; letter-spacing: 3px;
          color: rgba(255,255,255,0.5); text-transform: uppercase;
        }
        .rp-sub {
          font-family: 'Barlow', sans-serif;
          font-size: 10px; font-weight: 500;
          color: rgba(255,255,255,0.35);
          letter-spacing: 1.5px; text-transform: uppercase;
          margin-top: 6px;
        }
        .rp-card {
          background: #111;
          border-radius: 18px;
          padding: 28px 24px;
          width: 100%; max-width: 400px;
          border: 1px solid rgba(255,255,255,0.06);
          box-shadow: 0 24px 64px rgba(0,0,0,0.6);
          position: relative; z-index: 1;
        }
        .rp-card-title {
          font-family: 'Inter', sans-serif;
          font-size: 22px; font-weight: 900;
          letter-spacing: 2px; color: white;
          text-transform: uppercase; margin-bottom: 4px;
        }
        .rp-card-sub {
          font-family: 'Barlow', sans-serif;
          font-size: 13px; color: rgba(255,255,255,0.35);
          margin-bottom: 24px;
        }
        .rp-label {
          font-family: 'Barlow', sans-serif;
          font-size: 10px; font-weight: 700;
          letter-spacing: 2px; color: rgba(255,255,255,0.4);
          text-transform: uppercase; display: block; margin-bottom: 6px;
        }
        .rp-input-wrap { position: relative; margin-bottom: 14px; }
        .rp-input {
          width: 100%;
          background: rgba(255,255,255,0.04);
          border: 1.5px solid rgba(255,255,255,0.08);
          border-radius: 10px;
          padding: 13px 44px 13px 14px;
          color: white; font-size: 15px;
          font-family: 'Barlow', sans-serif;
          outline: none;
          transition: border 0.2s;
        }
        .rp-input:focus { border-color: rgba(223,255,0,0.4); }
        .rp-input::placeholder { color: rgba(255,255,255,0.2); }
        .rp-eye {
          position: absolute; right: 13px; top: 50%;
          transform: translateY(-50%);
          background: none; border: none; cursor: pointer;
          color: rgba(255,255,255,0.3); font-size: 17px; padding: 0;
        }
        .rp-error {
          background: rgba(255,60,60,0.08);
          border: 1px solid rgba(255,60,60,0.2);
          border-radius: 10px; padding: 11px 14px;
          color: #ff6b6b; font-size: 13px;
          font-family: 'Barlow', sans-serif;
          margin-bottom: 14px;
        }
        .rp-btn {
          width: 100%;
          background: #DFFF00;
          color: #000; font-weight: 900;
          font-size: 13px; letter-spacing: 3px;
          padding: 15px; border-radius: 10px;
          border: none; cursor: pointer;
          font-family: 'Inter', sans-serif;
          text-transform: uppercase;
          transition: opacity 0.2s, transform 0.1s;
        }
        .rp-btn:disabled { opacity: 0.5; cursor: not-allowed; }
        .rp-btn:not(:disabled):active { transform: scale(0.98); }
        .rp-success-icon { font-size: 48px; margin-bottom: 14px; }
        .rp-success-title {
          font-family: 'Inter', sans-serif;
          font-size: 22px; font-weight: 900;
          color: white; margin-bottom: 8px; letter-spacing: 1px;
        }
        .rp-success-sub {
          font-family: 'Barlow', sans-serif;
          font-size: 13px; color: rgba(255,255,255,0.4);
          margin-bottom: 24px;
        }
        .rp-success-btn {
          display: block;
          background: #DFFF00; color: #000;
          font-weight: 900; font-size: 13px; letter-spacing: 3px;
          padding: 15px; border-radius: 10px;
          text-decoration: none; text-align: center;
          font-family: 'Inter', sans-serif;
          text-transform: uppercase;
        }
      `}</style>

      <div className="rp-page">
        <div className="rp-bg-glow" />

        <div className="rp-logo">
          <div className="rp-icon">
            <img src={`data:image/webp;base64,${BEAST_ICON_B64}`} alt="Beast" />
          </div>
          <div className="rp-appname">BEAST</div>
          <div className="rp-slogan-row">
            <div className="rp-line" />
            <span className="rp-slogan">Dale duro</span>
            <div className="rp-line" />
          </div>
          <div className="rp-sub">Entrena cada maldito día</div>
        </div>

        <div className="rp-card">
          {status === "success" ? (
            <div style={{textAlign:"center"}}>
              <div className="rp-success-icon">✅</div>
              <div className="rp-success-title">¡Contraseña actualizada!</div>
              <div className="rp-success-sub">Ya puedes iniciar sesión con tu nueva contraseña.</div>
              <a href="/" className="rp-success-btn">Ir a la app →</a>
            </div>
          ) : (
            <>
              <div className="rp-card-title">Nueva contraseña</div>
              <div className="rp-card-sub">Elige una contraseña segura para tu cuenta.</div>

              <div className="rp-input-wrap">
                <label className="rp-label">Contraseña</label>
                <div style={{position:"relative"}}>
                  <input className="rp-input" type={showPass?"text":"password"} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Mínimo 6 caracteres" />
                  <button className="rp-eye" onClick={()=>setShowPass(p=>!p)}>{showPass?"🙈":"👁"}</button>
                </div>
              </div>

              <div className="rp-input-wrap" style={{marginBottom:22}}>
                <label className="rp-label">Confirmar contraseña</label>
                <input className="rp-input" style={{paddingRight:14}} type={showPass?"text":"password"} value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="Repite la contraseña" onKeyDown={e=>e.key==="Enter"&&handleSubmit()} />
              </div>

              {errorMsg && <div className="rp-error">{errorMsg}</div>}

              <button className="rp-btn" onClick={handleSubmit} disabled={status==="loading"}>
                {status==="loading" ? "Guardando..." : "Guardar contraseña →"}
              </button>
            </>
          )}
        </div>
      </div>
    </>
  );
}